async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const value=await response.json();if(response.status===401){signOut();throw Error('관리자 로그인이 필요합니다');}if(!response.ok)throw Error(reasons[value.reason]??'요청을 완료하지 못했습니다. 연결 설정과 작업 기록을 확인해 주세요');return value;}
const base=()=>'/api/admin/servers/'+encodeURIComponent(selected)+'/outline';
